import { ChangeDetectionStrategy, Component } from '@angular/core'
import {
  bootstrapApplication,
  provideClientHydration,
  withNoIncrementalHydration
} from '@angular/platform-browser'

@Component({
  selector: 'app-root',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <a class="govuk-skip-link" href="#main-content" data-module="govuk-skip-link">
      Skip to main content
    </a>
    <main class="govuk-main-wrapper" id="main-content">
      <!-- Complete static markup from the focused GOV.UK records. -->
    </main>
  `
})
export class AppComponent {}

const app = await bootstrapApplication(AppComponent, {
  providers: [provideClientHydration(withNoIncrementalHydration())]
})
await app.whenStable()
await new Promise<void>((resolve) => requestAnimationFrame(() => resolve()))

const scope = document.querySelector('app-root')
if (!scope) throw new Error('Angular application root was not found')

const { initAll } = await import('govuk-frontend')
initAll({
  scope,
  onError(error) { throw error }
})

