import {
  ChangeDetectionStrategy,
  Component,
  DestroyRef,
  ElementRef,
  afterNextRender,
  inject
} from '@angular/core'

const initialisedScopes = new WeakSet<Element>()

@Component({
  selector: 'app-govuk-panel',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `<!-- Complete static GOV.UK component markup. -->`
})
export class GovukPanelComponent {
  private readonly destroyRef = inject(DestroyRef)
  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef)

  constructor() {
    afterNextRender({
      write: () => { void this.initialise() }
    })
  }

  private async initialise() {
    const scope = this.host.nativeElement
    if (initialisedScopes.has(scope)) return
    initialisedScopes.add(scope)

    try {
      const { initAll } = await import('govuk-frontend')
      if (this.destroyRef.destroyed || !scope.isConnected) {
        initialisedScopes.delete(scope)
        return
      }
      initAll({ scope, onError(error) { throw error } })
    } catch (error) {
      initialisedScopes.delete(scope)
      queueMicrotask(() => { throw error })
    }
  }
}
